INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl von RAM für ein System entscheidend?', 2, '[{"text": "Kompatibilität mit dem Motherboard", "correct": true, "because": "Falscher RAM funktioniert nicht"}, {"text": "Farbe der Module", "correct": false, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist mehr RAM immer gleichbedeutend mit besserer Leistung?', 1, '[{"text": "Nein", "correct": true, "because": "Nutzen hängt von Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Überschüssiger RAM bleibt ungenutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die RAM-Leistung wichtig?', 5, '[{"text": "Kapazität", "correct": true, "because": "Mehr Daten können gespeichert werden"}, {"text": "Taktfrequenz", "correct": true, "because": "Schnellere Datenverarbeitung"}, {"text": "Gewicht des Moduls", "correct": false, "because": "Irrelevant für Leistung"}, {"text": "Latenzzeit", "correct": true, "because": "Beeinflusst Zugriffsgeschwindigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über RAM richtig? a) Höhere Taktfrequenz verbessert immer die Leistung. b) RAM-Größe beeinflusst Multitasking.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Taktfrequenz abhängig von System"}, {"text": "Nur b) stimmt", "correct": true, "because": "Mehr RAM hilft bei Multitasking"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist nicht immer wahr"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung von RAM für ein Büro-PC ignorieren?', 2, '[{"text": "RGB-Beleuchtung", "correct": true, "because": "Kein Einfluss auf Leistung"}, {"text": "Kapazität", "correct": false, "because": "Wichtig für Anwendungen"}, {"text": "Taktfrequenz", "correct": false, "because": "Beeinflusst Geschwindigkeit"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl von RAM für ein System entscheidend?', 2, '[{"text": "Kompatibilität mit dem Motherboard", "correct": true, "because": "Falscher RAM funktioniert nicht"}, {"text": "Farbe der Module", "correct": false, "because": "Nur optisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist mehr RAM immer besser für die Systemleistung?', 1, '[{"text": "Nein", "correct": true, "because": "Nutzen hängt von der Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Übermäßiger RAM bleibt ungenutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Leistung von RAM?', 5, '[{"text": "Taktfrequenz", "correct": true, "because": "Bestimmt die Datenrate"}, {"text": "Kapazität", "correct": true, "because": "Mehr Speicher für Prozesse"}, {"text": "Gewicht der Module", "correct": false, "because": "Kein Einfluss"}, {"text": "Latenzzeit", "correct": true, "because": "Beeinflusst Zugriffsgeschwindigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über RAM richtig? a) DDR4 ist schneller als DDR3. b) RAM-Größe beeinflusst die CPU direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DDR4 hat höhere Bandbreite"}, {"text": "Beides stimmt", "correct": false, "because": "RAM-Größe wirkt indirekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "DDR4 ist tatsächlich schneller"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung von RAM für Gaming ignorieren?', 2, '[{"text": "Design der Module", "correct": true, "because": "Kein Einfluss auf Leistung"}, {"text": "Taktfrequenz", "correct": false, "because": "Wichtig für Spiele"}, {"text": "Kapazität", "correct": false, "because": "Entscheidend für Ladezeiten"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl von RAM für einen Gaming-PC entscheidend?', 2, '[{"text": "Taktfrequenz", "correct": true, "because": "Schneller RAM verbessert FPS"}, {"text": "Design der Module", "correct": false, "because": "Ästhetik ohne Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist RAM mit höherer Kapazität immer schneller?', 1, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Taktfrequenz ab"}, {"text": "Ja", "correct": false, "because": "Kapazität und Geschwindigkeit sind getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für die RAM-Leistung wichtig?', 5, '[{"text": "Taktfrequenz", "correct": true, "because": "Bestimmt Datenrate"}, {"text": "Latenzzeit", "correct": true, "because": "Beeinflusst Zugriffsgeschwindigkeit"}, {"text": "Farbe der Module", "correct": false, "because": "Kein Leistungsfaktor"}, {"text": "Kapazität", "correct": true, "because": "Unterstützt mehr parallele Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über RAM richtig? a) Mehr RAM verbessert die Grafikleistung. b) RAM-Takt muss zum Motherboard passen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Grafik hängt von GPU ab"}, {"text": "Nur b) stimmt", "correct": true, "because": "Kompatibilität ist essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist wahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung von RAM für ein Büro-PC ignorieren?', 2, '[{"text": "Maximale Taktfrequenz", "correct": false, "because": "Wichtig für Leistung"}, {"text": "RGB-Beleuchtung", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Kompatibilität", "correct": false, "because": "Entscheidend für Betrieb"}]');
